-- Flagship learning resources from authoritative sources (hand-curated, reachability-checked by the fetcher).
-- CS50 is also collected automatically as a channel + playlists (proper source, keyless RSS).
INSERT INTO source_configs (name, source_type, config)
SELECT v.name, v.stype, v.config::jsonb
FROM (VALUES
  ('Curated - flagship courses', 'curated', $json$
  {"items": [
    {"title": "CS50x: Introduction to Computer Science", "url": "https://cs50.harvard.edu/x/", "source_name": "Harvard CS50", "category": "course", "difficulty": "beginner", "tags": ["cs50", "computer science", "python", "algorithms", "web"], "description": "Harvard's flagship introduction to computer science and programming: algorithms, data structures, Python, SQL, web development."},
    {"title": "CS50P: Introduction to Programming with Python", "url": "https://cs50.harvard.edu/python/", "source_name": "Harvard CS50", "category": "course", "difficulty": "beginner", "tags": ["cs50", "python"], "description": "Programming with Python from scratch: functions, conditionals, loops, exceptions, files, regular expressions, OOP."},
    {"title": "CS50W: Web Programming with Python and JavaScript", "url": "https://cs50.harvard.edu/web/", "source_name": "Harvard CS50", "category": "course", "difficulty": "intermediate", "tags": ["cs50", "web", "django", "javascript", "sql"], "description": "Full-stack web development with Django, JavaScript, SQL, and scalable web application design."},
    {"title": "CS50 Cybersecurity", "url": "https://cs50.harvard.edu/cybersecurity/", "source_name": "Harvard CS50", "category": "course", "difficulty": "beginner", "tags": ["cs50", "cybersecurity", "security"], "description": "Introduction to cybersecurity: threats, attacks, defenses, passwords, cryptography, and secure systems."},
    {"title": "Full Stack Open", "url": "https://fullstackopen.com/en/", "source_name": "University of Helsinki", "category": "course", "difficulty": "intermediate", "tags": ["web", "react", "node", "javascript", "typescript", "graphql"], "description": "Modern web development with React, Node.js, MongoDB, TypeScript, GraphQL, and CI/CD — free university course."},
    {"title": "MDN Learn Web Development", "url": "https://developer.mozilla.org/en-US/docs/Learn", "source_name": "MDN", "category": "course", "difficulty": "beginner", "tags": ["web", "html", "css", "javascript"], "description": "MDN's structured curriculum for front-end web development: HTML, CSS, JavaScript, accessibility, and frameworks."},
    {"title": "freeCodeCamp Curriculum", "url": "https://www.freecodecamp.org/learn/", "source_name": "freeCodeCamp", "category": "course", "difficulty": "beginner", "tags": ["web", "javascript", "python", "sql", "data"], "description": "Free certification curriculum: responsive web design, JavaScript, data structures, Python, relational databases, and more."},
    {"title": "The Odin Project", "url": "https://www.theodinproject.com/", "source_name": "The Odin Project", "category": "course", "difficulty": "beginner", "tags": ["web", "javascript", "node", "ruby", "full stack"], "description": "Free open-source full-stack web development curriculum built around real projects."},
    {"title": "MIT Missing Semester", "url": "https://missing.csail.mit.edu/", "source_name": "MIT", "category": "course", "difficulty": "beginner", "tags": ["devtools", "shell", "bash", "git", "vim"], "description": "MIT's course on the tools that aren't taught but are essential: shell, scripting, editors, git, debugging, profiling."},
    {"title": "MIT 6.006 Introduction to Algorithms", "url": "https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/", "source_name": "MIT OpenCourseWare", "category": "course", "difficulty": "intermediate", "tags": ["algorithms", "data structures", "computer science"], "description": "MIT OpenCourseWare introduction to algorithms and data structures: sorting, hashing, graphs, dynamic programming."},
    {"title": "MIT 6.046J Design and Analysis of Algorithms", "url": "https://ocw.mit.edu/courses/6-046j-design-and-analysis-of-algorithms-spring-2015/", "source_name": "MIT OpenCourseWare", "category": "course", "difficulty": "advanced", "tags": ["algorithms", "data structures", "computer science", "dynamic programming"], "description": "MIT OpenCourseWare advanced algorithms: divide and conquer, randomization, dynamic programming, and complexity analysis."},
    {"title": "Teach Yourself Computer Science", "url": "https://teachyourselfcs.com/", "source_name": "Teach Yourself CS", "category": "path", "difficulty": "intermediate", "tags": ["computer science", "algorithms", "systems", "networking", "databases"], "description": "Curated curriculum mapping the nine core computer science subjects to the best free books and courses."},
    {"title": "GitHub Skills", "url": "https://skills.github.com/", "source_name": "GitHub", "category": "course", "difficulty": "beginner", "tags": ["git", "github", "ci/cd", "devtools"], "description": "Hands-on interactive GitHub courses: Git basics, GitHub Actions, Pages, code review, and security."},
    {"title": "Atlassian Git Tutorials", "url": "https://www.atlassian.com/git/tutorials", "source_name": "Atlassian", "category": "tutorial", "difficulty": "beginner", "tags": ["git", "version control", "devtools"], "description": "Comprehensive Git and version control tutorials: branching, merging, rebasing, workflows."},
