    {"title": "Hack The Box Academy", "url": "https://academy.hackthebox.com/", "source_name": "Hack The Box", "category": "course", "difficulty": "intermediate", "tags": ["cybersecurity", "pentest", "ethical hacking", "active directory"], "description": "Structured penetration testing and cybersecurity modules with labs, from fundamentals to advanced exploitation."},
    {"title": "OverTheWire Wargames", "url": "https://overthewire.org/wargames/", "source_name": "OverTheWire", "category": "course", "difficulty": "beginner", "tags": ["linux", "bash", "security", "ethical hacking"], "description": "Progressive wargames that teach Linux, shell, and security fundamentals through hands-on challenges."},
    {"title": "Linux Foundation: Introduction to Linux (LFS101)", "url": "https://training.linuxfoundation.org/training/introduction-to-linux/", "source_name": "Linux Foundation", "category": "course", "difficulty": "beginner", "tags": ["linux", "bash", "systemd", "sysadmin"], "description": "Free official Linux Foundation course covering the Linux filesystem, command line, processes, networking, and system administration."},
    {"title": "Linux Upskill Challenge", "url": "https://linuxupskillchallenge.org/", "source_name": "Linux Upskill Challenge", "category": "course", "difficulty": "intermediate", "tags": ["linux", "sysadmin", "bash", "server"], "description": "Month-long practical Linux server administration course: users, permissions, services, networking, and security."},
    {"title": "Cisco Networking Basics", "url": "https://www.netacad.com/courses/networking-basics", "source_name": "Cisco Networking Academy", "category": "course", "difficulty": "beginner", "tags": ["network", "tcp/ip", "routing", "switching"], "description": "Cisco Networking Academy introduction to networking: protocols, IP addressing, routing, and switching."},
    {"title": "Google Machine Learning Crash Course", "url": "https://developers.google.com/machine-learning/crash-course", "source_name": "Google", "category": "course", "difficulty": "beginner", "tags": ["machine learning", "tensorflow", "ai", "python"], "description": "Google's fast-paced, practical introduction to machine learning with TensorFlow, featuring video lectures and exercises."},
    {"title": "fast.ai: Practical Deep Learning for Coders", "url": "https://course.fast.ai/", "source_name": "fast.ai", "category": "course", "difficulty": "intermediate", "tags": ["deep learning", "pytorch", "machine learning", "ai"], "description": "Practical deep learning course teaching model training with PyTorch, from vision and NLP to deployment."},
    {"title": "Kaggle Learn", "url": "https://www.kaggle.com/learn", "source_name": "Kaggle", "category": "course", "difficulty": "beginner", "tags": ["machine learning", "python", "data science", "pandas", "sql"], "description": "Free micro-courses in Python, pandas, SQL, machine learning, and data visualization with hands-on notebooks."}
  ]}
  $json$)
) AS v(name, stype, config)
WHERE NOT EXISTS (SELECT 1 FROM source_configs s WHERE s.name = v.name);

INSERT INTO source_configs (name, source_type, config)
SELECT v.name, 'youtube', v.config::jsonb
FROM (VALUES
  ('YouTube - CS50', '{"channel_ids": ["UCcabW7890RKJzL968QWEykA"]}'),
  ('YouTube - CS50 playlists', '{"channel_handles": ["cs50"], "max_playlists_per_channel": 8}')
) AS v(name, config)
WHERE NOT EXISTS (SELECT 1 FROM source_configs s WHERE s.name = v.name);
